#include "rpg/visual_session.hpp"
#include <iostream>
#include <stdexcept>
using namespace rpg;
using namespace rpg::presentation;
void check(bool ok){if(!ok){throw std::runtime_error("visual contract failed");}}
EncounterSetup duel(){auto s=team_reference_setup();s.roster={{"A1",Team::A,100,10,200},{"B1",Team::B,100,5,100}};s.loadouts.resize(1);s.loadouts.push_back({"B1",{{1,"Basic","B1-basica",{}}}});s.rules.skills.erase(s.rules.skills.begin()+3,s.rules.skills.end());s.rules.skills.push_back({"B1-basica","B1",0,TargetRule::Enemy,{{EffectKind::Damage}}});s.rules.timing=TimingProfile::FixedRounds;return s;}
void atomic_rejection(){VisualSession v(duel());const auto before=v.state();auto r=v.submit(before.revision,1,"missing");check(r.error==VisualError::CoreRejected && v.state().combat==before.combat && v.state().revision==before.revision);}
void stale_and_enemy(){VisualSession v(duel());auto token=v.state().revision;check(v.submit(token,1,"B1").accepted());auto before=v.state();check(before.automatic);check(v.submit(token,1,"B1").error==VisualError::StaleCommand);check(v.submit(before.revision,1,"B1").error==VisualError::NotPlayerTurn);check(v.state().combat==before.combat);check(v.step_automatic().accepted());check(!v.state().automatic);}
void matches_core(){auto s=duel();LocalSession core(s.roster,s.rules,CombatProfile::Team,s.loadouts);VisualSession v(s);check(v.submit(0,1,"B1").accepted());check(core.apply_slot(1,"B1").accepted());check(v.state().combat==core.battle().snapshot());auto a=core.battle().choose_automatic_action();check(a && core.apply(*a).accepted());check(v.step_automatic().accepted());check(v.state().combat==core.battle().snapshot());}
void finish_reset(){auto s=duel();s.roster[1].max_health=1;VisualSession v(s);check(v.submit(0,1,"B1").accepted());auto ended=v.state();check(ended.combat.battle.phase==Phase::Finished && ended.progress.credits==10);check(v.submit(ended.revision,1,"B1").error==VisualError::Finished);check(v.step_automatic().error==VisualError::Finished);v.reset();check(v.state().progress.attempt==2 && v.state().progress.credits==10);check(v.submit(ended.revision,1,"B1").error==VisualError::StaleCommand);}
void passive_and_condition(){VisualSession v;auto s=v.state();check(!s.abilities.empty());auto passive=team_reference_setup();passive.roster[0].speed=1;passive.roster[1].speed=999;VisualSession p(passive);auto view=p.state();check(view.combat.battle.current_actor=="A2");auto r=p.submit(view.revision,2,"B1");check(r.error==VisualError::CoreRejected && p.state().combat==view.combat);auto conditional=team_reference_setup();conditional.roster[2].speed=999;VisualSession c(conditional);auto initial=c.state();check(initial.combat.battle.current_actor=="A3");check(c.submit(initial.revision,3,"A3").error==VisualError::CoreRejected && c.state().combat==initial.combat);}
void bounded_automatic(){auto s=duel();s.roster[0].speed=1;s.roster[1].speed=999;s.rules.timing=TimingProfile::ActionBar;s.rules.action_budget=std::nullopt;s.roster[0].max_health=100000;VisualSession v(s);for(int i=0;i<256;++i){check(v.step_automatic().accepted());}auto before=v.state();check(v.step_automatic().error==VisualError::SafetyStop);check(v.state().combat==before.combat && v.state().stopped);v.reset();check(!v.state().stopped);}
int main(){try{atomic_rejection();stale_and_enemy();matches_core();finish_reset();passive_and_condition();bounded_automatic();std::cout<<"VIS_TESTS_RESULT passed=6 total=6\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
